$retryQueries=[];
$result=AiPhotoSelection::enrich($stationery,new PhotoProvider('invalid'),static function(string $query)use(&$retryQueries,$stationeryStore,$militaryRecord):array{$retryQueries[]=$query;return $query==='notebook planner journal on desk'?[]:[$stationeryStore,$militaryRecord];});
selectionCheck($retryQueries===['notebook planner product photo','notebook planner journal on desk']&&$result['design']['photoSelection']['status']==='no_matches'&&$result['design']['photoSelection']['assignments']===[],'No suitable writing-goods photo remains unassigned after one bounded search retry');
$stationeryCards=['design'=>['imageSlots'=>[['id'=>'section-1','query'=>'paper notebooks stationery','automatic'=>true],['id'=>'section-2','query'=>'paper planners stationery','automatic'=>true]]]];$plannerPhoto=['id'=>'commons:planner','name'=>'Weekly planner open.jpg','description'=>'An open weekly planner on a desk','url'=>'https://upload.wikimedia.org/planner.jpg','author'=>'Author','license'=>'CC0','sourceUrl'=>'https://commons.wikimedia.org/wiki/File:Planner.jpg','licenseUrl'=>'https://creativecommons.org/publicdomain/zero/1.0/','kind'=>'commons'];$cardRetryQueries=[];
$result=AiPhotoSelection::enrich($stationeryCards,new PhotoProvider('invalid'),static function(string $query)use(&$cardRetryQueries,$notebookPhoto,$plannerPhoto):array{$cardRetryQueries[]=$query;return match($query){'blank open notebook'=>[$notebookPhoto],'planning session planner'=>[$plannerPhoto],default=>[]};});
selectionCheck($cardRetryQueries===['paper notebooks stationery','blank open notebook','paper planners stationery','planning session planner']&&$result['design']['photoSelection']['assignments']===['section-1'=>'commons:notebook','section-2'=>'commons:planner']&&count($result['design']['photoSelection']['photos'])===2,'Each product-card photo gets a cached, subject-specific Commons fallback query and only matching candidates are assigned');
$weeklyAgenda=['id'=>'commons:weekly-agenda','name'=>'Weekly agenda open on desk.jpg','description'=>'A paper appointment diary with a weekly layout','url'=>'https://upload.wikimedia.org/weekly-agenda.jpg','author'=>'Author','license'=>'CC BY-SA 4.0','sourceUrl'=>'https://commons.wikimedia.org/wiki/File:Weekly_agenda.jpg','licenseUrl'=>'https://creativecommons.org/licenses/by-sa/4.0/','kind'=>'commons'];
$result=AiPhotoSelection::enrich(['design'=>['imageSlots'=>[['id'=>'section-2','query'=>'planner paper stationery','automatic'=>true,'required'=>true]]]],new PhotoProvider('invalid'),static fn($query)=>$query==='planning session planner'?[$weeklyAgenda]:[]);
