$uniqueCards=AiPhotoSelection::enrich(['design'=>['imageSlots'=>[['id'=>'section-1','query'=>'notebook paper stationery','automatic'=>true,'required'=>true],['id'=>'section-2','query'=>'planner paper stationery','automatic'=>true,'required'=>true]]]],$duplicateChoices,static fn($query)=>match($query){'notebook paper stationery','planner paper stationery'=>[$sharedPhoto],'blank open notebook'=>[$notebookPhoto],'planning session planner'=>[$secondPlannerPhoto],default=>[]});
selectionCheck($uniqueCards['design']['photoSelection']['assignments']===['section-1'=>'commons:shared','section-2'=>'commons:planner-2'],'Required product cards never reuse the same image when distinct subject-matched candidates exist');
$constrainedCards=AiPhotoSelection::enrich(['design'=>['imageSlots'=>[['id'=>'section-1','query'=>'notebook paper stationery','automatic'=>true,'required'=>true],['id'=>'section-2','query'=>'planner paper stationery','automatic'=>true,'required'=>true]]]],new PhotoProvider('{"selections":[{"slotId":"section-1","photoId":"commons:shared"},{"slotId":"section-2","photoId":"commons:shared"}]}'),static fn($query)=>match($query){'notebook paper stationery','planner paper stationery'=>[$sharedPhoto],'blank open notebook'=>[$notebookPhoto],default=>[]});
