$allSlotPhotos=AiPhotoSelection::enrich($allSlots,new PhotoProvider('{"selections":[{"slotId":"hero","photoId":"commons:shared"},{"slotId":"section-1","photoId":"commons:shared"},{"slotId":"section-2","photoId":"commons:shared"}]}'),static fn($query)=>match($query){'notebook planner journal on desk'=>[$sharedPhoto,$notebookPhoto,$secondPlannerPhoto],'notebook paper stationery'=>[$sharedPhoto],'planner paper stationery'=>[$sharedPhoto],'blank open notebook'=>[$sharedPhoto,$notebookPhoto],'planning session planner'=>[$sharedPhoto,$secondPlannerPhoto],default=>[]});
