$requiredMissing=false;try{AiPhotoSelection::enrich(['design'=>['imageSlots'=>[['id'=>'section-2','query'=>'planner paper stationery','automatic'=>true,'required'=>true]]]],new PhotoProvider('invalid'),static fn()=>[]);}catch(AiProviderFailure $failure){$requiredMissing=$failure->category==='photo_unavailable';}
